INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('78dc64cb-c37a-50c3-a05d-1d0fcf946c43'::uuid, '4ea838d6-ce33-5f09-a69c-ef54c4c75179'::uuid, 'Pompage solaire', '"Le système de pompage solaire comprend : Des panneaux photovoltaïques assurant la conversion de l’énergie solaire en électricité. Un variateur de pompage solaire (onduleur spécifique) permettant d’adapter et de réguler l’énergie produite pour le fonctionnement optimal de la pompe. Une pompe immergée/submersible dimensionnée en fonction du débit', '["https://lechantier.ma/uploads/media/ec259255d574.webp", "https://lechantier.ma/uploads/media/1f4002977a90.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ec259255d574.webp', 'Fès', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('12706073-7dd8-597d-875b-e295402f0fb9'::uuid, '4ea838d6-ce33-5f09-a69c-ef54c4c75179'::uuid, 'Installation solaire on grid 5kwc', '"Le système solaire photovoltaïque connecté au réseau présente plusieurs avantages importants : Réduction de la facture d’électricité : l’énergie produite par vos panneaux est directement consommée dans vos locaux, ce qui diminue considérablement vos dépenses en électricité. Valorisation du surplus : l’excédent d’énergie non consommé peut être in', '["https://lechantier.ma/uploads/media/58a5cbd0b71e.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/58a5cbd0b71e.webp', 'Fès', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('af4d631c-c18c-5ef1-b67f-3477c689839a'::uuid, '4ea838d6-ce33-5f09-a69c-ef54c4c75179'::uuid, 'Réalisation — ISSMATELEC', NULL, '["https://lechantier.ma/uploads/media/1f4002977a90.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/1f4002977a90.webp', 'Fès', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
