INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('37f99208-d58b-53c5-bb14-794c5715ab6d'::uuid, '15f0fc07-2ed1-5095-a32f-fece22e60837'::uuid, 'VILLA', 'Travaux de climatisation sur chantier – Villa (sous-sol, RDC, étage).', '["https://lechantier.ma/uploads/media/2c448d92987f.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/2c448d92987f.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e64972c3-13f3-57d9-8cb1-d21f32b845cd'::uuid, '4d7e4e15-3b78-52f0-93a7-8f33635e2157'::uuid, 'HOTEL SONGOU', '''installation complète d''un système de climatisation gainable pour l''Hôtel Soungou à Marrakech. Ce projet comprenait l''étude des besoins thermiques, l''installation discrète des unités avec intégration architecturale optimale, et le réglage précis des flux d''air pour un confort homogène dans les espaces communs et chambres', '["https://lechantier.ma/uploads/media/abf75bb814ca.webp", "https://lechantier.ma/uploads/media/f0554496b83e.webp", "https://lechantier.ma/uploads/media/6d32f69314b7.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/abf75bb814ca.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9d32ce4b-ac08-52ae-8248-2fc9a3a41456'::uuid, '4d7e4e15-3b78-52f0-93a7-8f33635e2157'::uuid, 'AUTRES', 'Gallerie de mes réalisations : installations neuves, dépannages techniques et maintenance d''équipements climatiques pour divers clients. Preuves concrètes de mon expertise polyvalente en solutions thermiques', '["https://lechantier.ma/uploads/media/751f2c8ecdb3.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/751f2c8ecdb3.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.2.2' LIMIT 1));
