INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('bb319dbe-466a-5e74-b3e2-6b44ec3126a5'::uuid, '87b03305-06bc-5cbf-b18f-d07158b5275d'::uuid, 'installation d''une hotte', 'Installation de hotte par NB3S NB3S vous propose un service complet d’installation de hottes d’aspiration, adapté aussi bien aux cuisines professionnelles qu’aux espaces industriels. Notre équipe qualifiée assure une mise en place conforme aux normes de sécurité et de ventilation, garantissant une performance optimale et une évacuation efficace des', '["https://lechantier.ma/uploads/media/7fe9a4892749.webp", "https://lechantier.ma/uploads/media/db9b7a9ab613.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/7fe9a4892749.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.2.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('7df2b7ba-3b1b-5118-9af0-bf7bb022e6c9'::uuid, '87b03305-06bc-5cbf-b18f-d07158b5275d'::uuid, 'système d''extraction et ventilation', 'NB3S assure l’étude, la fourniture et l’installation de systèmes de ventilation performants, adaptés aux besoins des particuliers, commerces et industries. Nos solutions garantissent un renouvellement d’air optimal, l’évacuation des polluants et une meilleure qualité de l’air intérieur. Grâce à notre expertise, nous vous offrons un confort thermiqu', '["https://lechantier.ma/uploads/media/d743ae15913f.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/d743ae15913f.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.2.3' LIMIT 1));
