INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('3fb48a54-4c40-5018-b551-9c0e072919f5'::uuid, '28faa744-4aa5-5a89-abca-e6da0ec3b2ae'::uuid, 'Salle de bain', 'Envisagez-vous de rénover votre salle de bain et de la rendre plus confortable et élégante ? Avec Achraf Plomberie, nous vous fournissons un service complet de configuration de salle de bains, de la conception à l''installation. Nous nous ocitons des plus petits détails : du choix des articles sanitaires, de l''installation de douches et de robinet', '["https://lechantier.ma/uploads/media/3c7b45331206.webp", "https://lechantier.ma/uploads/media/1390ad157371.webp", "https://lechantier.ma/uploads/media/7301f8c3c705.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/3c7b45331206.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5ee2da10-d310-5885-b6f7-ee20a7a44328'::uuid, '28faa744-4aa5-5a89-abca-e6da0ec3b2ae'::uuid, 'Filter', 'نقوم بتركيب فلاتر الماء بطريقة احترافية لضمان ماء نقي وصالح للاستعمال اليومي.يساعد الفلتر على إزالة الشوائب، والكلور، والرواسب، والروائح غير المرغوب فيها، مما يحسّن طعم وجودة الماء يتم التركيب بسرعة وبأدوات ذات جودة عالية، مع احترام معايير السلامة في السباكة. كما يساهم الفلتر في حماية الأدوات المنزلية والتركيبات الصحية من التكلّس والترسبات', '["https://lechantier.ma/uploads/media/d66052dcbdd0.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/d66052dcbdd0.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.2' LIMIT 1));
